<?php
class HrMetricsController {
 private $m;public function __construct(){if(!isStaffAdmin())redirect('login');$this->m=new HrSuite();}
 public function index(){if(!access_can('metrics.operational')&&!access_can('metrics.strategic'))require_capability('metrics.operational');$cid=requireAdminCompany();$month=preg_match('/^\d{4}-\d{2}$/',$_GET['month']??'')?$_GET['month']:date('Y-m');$start=$month.'-01';$end=date('Y-m-t',strtotime($start));$attendance=$this->m->one("SELECT COALESCE(SUM(planned_minutes),0) planned,COALESCE(SUM(CASE WHEN status='no_show' THEN planned_minutes ELSE 0 END),0) absent,SUM(status='late') late,SUM(status='early_leave') early FROM attendance_day_summary WHERE company_id=? AND work_date BETWEEN ? AND ?",[$cid,$start,$end]);$hires=$this->m->one('SELECT COUNT(*) n FROM users WHERE company_id=? AND hire_date BETWEEN ? AND ?',[$cid,$start,$end]);$active=$this->m->one("SELECT COUNT(*) n FROM users WHERE company_id=? AND role='empleado' AND is_active=1",[$cid]);$counts=$this->m->dashboardCounts($cid);$ats=$this->m->one('SELECT COUNT(*) total,SUM(ja.status=\'hired\') hired,AVG(DATEDIFF(COALESCE((SELECT MIN(created_at) FROM application_events ae WHERE ae.application_id=ja.id AND ae.to_stage=\'hired\'),NOW()),ja.created_at)) avg_days FROM job_applications ja JOIN job_vacancies jv ON jv.id=ja.vacancy_id WHERE jv.company_id=? AND ja.created_at BETWEEN ? AND DATE_ADD(?,INTERVAL 1 DAY)',[$cid,$start,$end]);$this->view('admin/hr_metrics/index',compact('month','attendance','hires','active','counts','ats'));}
 private function view($v,$d){require APPROOT.'/views/'.$v.'.php';}
}
